    ofstream sortie("repertoire.txt");
    for (int i = 0; i < n; i++) {
        string nom, tel;
        cin >> nom >> tel;
        sortie << nom << " " << tel << "\n";
    }
    sortie.close();

    ifstream entree("repertoire.txt");
    if (!entree.is_open()) {
        cerr << "Impossible d'ouvrir le fichier\n";
        return 1;
    }
    string nom, tel;
    while (entree >> nom >> tel) {
        cout << nom << " : " << tel << "\n";
        cout << "\n";
    }
    entree.close();
    return 0;
}
